package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPublicCommunityQuestionsTest extends JdbcCommunityQuestionsTest {
 PublicCommunityQuestions publicQa;OperatorActor reviewer;
 @BeforeEach void publicationSetup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_public_qa_audit");jdbc.update("DELETE FROM community_qa_publication_event");jdbc.update("DELETE FROM community_qa_publication");jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_review) VALUES(4,'synthetic-public-qa-reviewer','unused','13800000004',1)");reviewer=operator(4);jdbc.update("UPDATE auth_session SET app_id='synthetic-app',point_identity_source='VERIFIED_WECHAT' WHERE id=?",owner.session());questions=new CommunityQuestions(db,policies,new PointLedger(db,new PointTaskPolicies(db,policies.operators),"synthetic-app",false,false));publicQa=new PublicCommunityQuestions(db,policies.operators,policies,new ExperienceModeration(db,policies.operators,false),true,"synthetic-app");}
 @AfterEach void publicationCleanup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_public_qa_audit");}
 long pair(){long c=submit(configure("LEAVE_MESSAGE"));questions.assign(manager,c,key(),assign(1,2));questions.write(first,c,"reply",key(),message(2,"本次明确运营答复"));return c;}
 ObjectNode selectors(long c){long q=jdbc.queryForObject("SELECT MIN(id) FROM community_qa_message WHERE case_id=? AND sender_type='OWNER'",Long.class,c),a=jdbc.queryForObject("SELECT MAX(id) FROM community_qa_message WHERE case_id=? AND sender_type='OPERATOR'",Long.class,c);return json.createObjectNode().put("question_message_id",q).put("answer_message_id",a);}
 ObjectNode consent(long c){var b=selectors(c);return b.put("preview_hash",publicQa.preview(owner,c,b).get("preview_hash").toString()).put("consent_version",PublicCommunityQuestions.CONSENT).put("consent",true);}
 long apply(long c){return publicQa.submit(owner,c,key(),consent(c)).path("data").path("application_id").asLong();}
 ObjectNode review(long rev,String decision){var b=json.createObjectNode().put("expected_revision",rev).put("decision",decision);if(decision.equals("APPROVE"))b.putNull("reason_code");else b.put("reason_code","PRIVACY");return b;}
 void approve(long id){publicQa.moderate(reviewer,id,key(),review(1,"APPROVE"));}
 String publicId(long id){return jdbc.queryForObject("SELECT public_id FROM community_qa_publication WHERE id=?",String.class,id);}
 @Test void explicitConsentReviewAndSameModelProjectionNeverExposePrivateDetail(){long c=pair();var p=publicQa.preview(owner,c,selectors(c));assertEquals(Set.of("preview","preview_hash"),p.keySet());long id=apply(c);assertTrue(((List<?>)publicQa.list(peer,2,null).get("items")).isEmpty());assertEquals(403,code(()->publicQa.pending(manager,1)));assertEquals(403,code(()->questions.detail(reviewer,c,1)));var queue=json.valueToTree(publicQa.pending(reviewer,1));assertTrue(queue.path("items").get(0).path("source_available").asBoolean());for(String hidden:List.of("case_id","owner_id","question_message_id","answer_message_id","sender_id","source_hash","admission_snapshot","plate_no","vin"))assertFalse(queue.toString().contains("\""+hidden+"\""),hidden);approve(id);var result=json.valueToTree(publicQa.detail(peer,2,publicId(id)));assertEquals(Set.of("public_id","model_id","category","question_text","answer_text","published_at"),json.convertValue(result.path("question"),Map.class).keySet());assertEquals(404,code(()->publicQa.detail(owner,2,publicId(id))));assertEquals(0,count("point_task_event"));}
 @Test void unknownOldOrWrongAppSourcesCannotBePromotedByClientProof(){jdbc.update("UPDATE auth_session SET point_identity_source='UNKNOWN' WHERE id=?",owner.session());long c=pair();assertEquals(409,code(()->publicQa.preview(owner,c,selectors(c))));jdbc.update("UPDATE auth_session SET point_identity_source='VERIFIED_WECHAT' WHERE id=?",owner.session());assertEquals(409,code(()->publicQa.preview(owner,c,selectors(c))));assertThrows(Exception.class,()->PublicCommunityQuestions.input(selectors(c).put("identity_source","VERIFIED_WECHAT").toString(),"preview"));var wrong=new PublicCommunityQuestions(db,policies.operators,policies,new ExperienceModeration(db,policies.operators,false),true,"other-app");long policy=jdbc.queryForObject("SELECT id FROM community_qa_service_policy WHERE status='PUBLISHED'",Long.class),verified=submit(policy);questions.assign(manager,verified,key(),assign(1,2));questions.write(first,verified,"reply",key(),message(2,"正式合成来源"));assertNotNull(publicQa.preview(owner,verified,selectors(verified)));assertEquals(409,code(()->wrong.preview(owner,verified,selectors(verified))));}
 @Test void fullRedactionBeforeClippingDoesNotSplitIdentifiersIntoVisibleFragments(){long p=configure("AVAILABLE");var b=question(p).put("message","x".repeat(290)+"13812345678 尾部PRIVATE_TAIL");long c=questions.create(owner,key(),b).path("data").path("case_id").asLong();questions.assign(manager,c,key(),assign(1,2));questions.write(first,c,"reply",key(),message(2,"网址https://private.example/a 邮箱abc@example.test 车牌京A12345 VIN LHGCM82633A004352"));String preview=db.json(publicQa.preview(owner,c,selectors(c)));assertFalse(preview.contains("138123"));assertFalse(preview.contains("private.example"));assertFalse(preview.contains("abc@example"));assertFalse(preview.contains("京A12345"));assertFalse(preview.contains("LHGCM82633A004352"));assertFalse(preview.contains("PRIVATE_TAIL"));assertTrue(preview.contains("[已隐藏]"));}
 @Test void onlyActualNearestOwnerQuestionAndAnswerInSameCaseCanBeSelected(){long c=pair();var old=selectors(c);long policy=jdbc.queryForObject("SELECT id FROM community_qa_service_policy WHERE status='PUBLISHED'",Long.class);questions.write(owner,c,"message",key(),follow(3,policy));questions.write(first,c,"reply",key(),message(4,"后续答复"));long newest=jdbc.queryForObject("SELECT MAX(id) FROM community_qa_message WHERE case_id=? AND sender_type='OPERATOR'",Long.class,c);assertEquals(409,code(()->publicQa.preview(owner,c,old.deepCopy().put("answer_message_id",newest))));assertNotNull(publicQa.preview(owner,c,old));assertEquals(404,code(()->publicQa.preview(peer,c,old)));assertEquals(404,code(()->publicQa.preview(owner,c,old.deepCopy().put("question_message_id",newest))));}
 @Test void bodyAndOriginalEventOrAuditTamperingCannotPublish(){long c=pair();var selectors=selectors(c);long q=selectors.path("question_message_id").asLong();String body=jdbc.queryForObject("SELECT body FROM community_qa_message WHERE id=?",String.class,q);jdbc.update("UPDATE community_qa_message SET body='changed' WHERE id=?",q);assertEquals(409,code(()->publicQa.preview(owner,c,selectors)));jdbc.update("UPDATE community_qa_message SET body=? WHERE id=?",body,q);jdbc.update("UPDATE audit_log SET is_deleted=1 WHERE action='COMMUNITY_QUESTION_CREATE' AND resource_id=?",c);assertEquals(409,code(()->publicQa.preview(owner,c,selectors)));jdbc.update("UPDATE audit_log SET is_deleted=0 WHERE action='COMMUNITY_QUESTION_CREATE' AND resource_id=?",c);jdbc.update("DELETE FROM community_qa_case_event WHERE case_id=? AND kind='CREATED'",c);assertEquals(409,code(()->publicQa.preview(owner,c,selectors)));}
 @Test void previewHashAndPermanentSubmissionBindOriginalBodyAndCurrentOriginalOwner(){long c=pair();var b=consent(c);assertEquals(409,code(()->publicQa.submit(owner,c,key(),b.deepCopy().put("preview_hash","a".repeat(64)))));String k=key();var original=publicQa.submit(owner,c,k,b);long id=original.path("data").path("application_id").asLong();approve(id);publicQa.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",2));jdbc.update("UPDATE vehicle SET user_id=2 WHERE id=1");expireKeys();var off=new PublicCommunityQuestions(db,policies.operators,policies,new ExperienceModeration(db,policies.operators,false),false,"synthetic-app");assertEquals(original.path("data"),off.submit(owner,c,k,b).path("data"));assertEquals(1,count("community_qa_publication"));assertEquals(400,code(()->off.submit(owner,c,k,b.deepCopy().put("preview_hash","b".repeat(64)))));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->off.submit(owner,c,k,b)));}
 @Test void withdrawalAndLatestEvidencePreventUuidAndStateRowRollbackRevival(){long c=pair(),id=apply(c);approve(id);String uuid=publicId(id);publicQa.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",2));assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));jdbc.update("UPDATE community_qa_publication SET status='APPROVED',revision=2 WHERE id=?",id);assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));jdbc.update("UPDATE community_qa_publication_event SET is_deleted=1 WHERE publication_id=? AND revision=3",id);assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));assertEquals(409,code(()->publicQa.moderate(reviewer,id,key(),review(1,"APPROVE"))));}
 @Test void activeConsentUniqueAndFreshSubmissionAfterWithdrawalHasNewUuid(){long c=pair(),id=apply(c);assertEquals(409,code(()->apply(c)));approve(id);String old=publicId(id);publicQa.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",2));long next=apply(c);approve(next);assertNotEquals(old,publicId(next));assertEquals(404,code(()->publicQa.detail(peer,2,old)));assertNotNull(publicQa.detail(peer,2,publicId(next)));}
 @Test void sourceChangesAndModelTamperingNeverCrossCurrentRecipientScope(){long c=pair(),id=apply(c);approve(id);String uuid=publicId(id);jdbc.update("INSERT INTO model(id,series_id,year,config_name,status) VALUES(2,1,'2027','另一个合成车型',1)");jdbc.update("UPDATE vehicle SET model_id=2 WHERE id=2");assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));jdbc.update("UPDATE community_qa_publication SET model_id=2 WHERE id=?",id);assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));jdbc.update("UPDATE vehicle SET model_id=1 WHERE id=2");jdbc.update("UPDATE community_qa_publication SET model_id=1,published_at=DATE_ADD(published_at,INTERVAL 1 DAY) WHERE id=?",id);assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));jdbc.update("UPDATE community_qa_publication SET published_at=? WHERE id=?",ReservationStore.time(clock.value),id);jdbc.update("UPDATE vehicle SET user_id=2 WHERE id=1");assertEquals(404,code(()->publicQa.detail(peer,2,uuid)));assertEquals(false,((Map<?,?>)((List<?>)publicQa.ownList(owner,c,1).get("items")).get(0)).get("visible"));publicQa.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",2));}
 @Test void disabledFeatureStillAllowsOwnStatusAndWithdrawalButNoNewPublicAccess(){long c=pair(),id=apply(c);approve(id);var off=new PublicCommunityQuestions(db,policies.operators,policies,new ExperienceModeration(db,policies.operators,false),false,"synthetic-app");assertEquals(503,code(()->off.preview(owner,c,selectors(c))));assertEquals(503,code(()->off.list(peer,2,null)));assertEquals(1L,off.ownList(owner,c,1).get("total"));off.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",2));assertEquals("WITHDRAWN",publicQa.application(id,false).get("status"));}
 @Test void invalidPreviewRowsNeverExposeInjectedPrivateFieldsToReviewer(){long c=pair(),id=apply(c);jdbc.update("UPDATE community_qa_publication SET preview=JSON_SET(preview,'$.owner_id',1,'$.question_text','private replacement') WHERE id=?",id);var pending=json.valueToTree(publicQa.pending(reviewer,1));assertTrue(pending.path("items").get(0).path("preview").isNull());assertFalse(pending.toString().contains("private replacement"));assertFalse(pending.toString().contains("owner_id"));assertEquals(409,code(()->publicQa.moderate(reviewer,id,key(),review(1,"APPROVE"))));}
 @Test void originalAuditSoftDeletionAndFailedReviewAuditNeverProducePublicSuccess(){long c=pair(),id=apply(c);String k=key();jdbc.execute("CREATE TRIGGER reject_public_qa_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->publicQa.moderate(reviewer,id,k,review(1,"APPROVE"))));assertEquals("PENDING",publicQa.application(id,false).get("status"));assertEquals(1,count("community_qa_publication_event"));jdbc.execute("DROP TRIGGER reject_public_qa_audit");publicQa.moderate(reviewer,id,k,review(1,"APPROVE"));jdbc.update("UPDATE audit_log SET is_deleted=1 WHERE action='PUBLIC_QA_MODERATE' AND resource_id=?",id);assertEquals(404,code(()->publicQa.detail(peer,2,publicId(id))));}
 @Test void concurrentSubmissionsHaveOneActiveWinnerAndApproveWithdrawSerialize()throws Exception{long c=pair();var b=consent(c);var pool=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);var x=pool.submit(()->{gate.await();return code(()->publicQa.submit(owner,c,key(),b));});var y=pool.submit(()->{gate.await();return code(()->publicQa.submit(owner,c,key(),b));});gate.countDown();var results=new ArrayList<>(List.of(x.get(30,TimeUnit.SECONDS),y.get(30,TimeUnit.SECONDS)));Collections.sort(results);assertEquals(List.of(200,409),results,"distinct submissions must have one active winner");long id=jdbc.queryForObject("SELECT id FROM community_qa_publication",Long.class);var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();return code(()->publicQa.moderate(reviewer,id,key(),review(1,"APPROVE")));});var w=pool.submit(()->{start.await();return code(()->publicQa.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",1)));});start.countDown();var race=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),w.get(30,TimeUnit.SECONDS)));Collections.sort(race);assertEquals(List.of(200,409),race,"approval and withdrawal must serialize on current revision");if("APPROVED".equals(publicQa.application(id,false).get("status")))publicQa.withdraw(owner,id,key(),json.createObjectNode().put("expected_revision",2));assertTrue(((List<?>)publicQa.list(peer,2,null).get("items")).isEmpty());}finally{pool.shutdownNow();}}
 @Test void publicReadsAreSideEffectFreeAndPrivateFollowupDoesNotExpandOldPublication(){long c=pair(),id=apply(c);approve(id);String uuid=publicId(id);int events=count("community_qa_publication_event"),audits=count("audit_log"),keys=count("idempotency_record");publicQa.list(peer,2,null);publicQa.detail(peer,2,uuid);publicQa.ownList(owner,c,1);assertEquals(events,count("community_qa_publication_event"));assertEquals(audits,count("audit_log"));assertEquals(keys,count("idempotency_record"));long p=jdbc.queryForObject("SELECT id FROM community_qa_service_policy WHERE status='PUBLISHED'",Long.class);questions.write(owner,c,"message",key(),follow(3,p).put("message","新补充不能自动公开"));assertFalse(db.json(publicQa.detail(peer,2,uuid)).contains("新补充"));assertNotNull(questions.detail(first,c,1));}
}
